/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> feetDoubleBassEighthsLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "An even stream of eighths split between two feet is the first double bass skill: the right foot plays the beats, the left foot the \"ands\", and together they sound like one drummer with a very fast kick. Every faster double bass pattern grows out of this.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Two pedals (or a double pedal), right foot leads: R on every beat, L on every \"and\", both feet at the same height and the same volume, heel up and loose, hands steady on quarters above.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 1 is the reference: if you cannot hear which foot is playing, it is right. Lines 2, 3 and 6 start and stop the stream so you practise getting in and out cleanly; line 4 moves the hand to the ride, line 5 is half-time, line 7 eighth hats over the feet, line 8 a crash on the one. Start slow — 60 is fine.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "Motörhead \"Overkill\" with Phil Taylor, Judas Priest and Accept in the early-80s heavy metal era, and the steady double-bass choruses of countless metal songs before they speed up to sixteenths.",
  ),
];
